def promotion_gate(model, holdout, probes, incumbent):
    checks = {
     'accuracy':   rmse(model, holdout) <= TH.rmse and
                   rmse(model, holdout) <= rmse(incumbent, holdout),
     'calibration':ece(model, holdout) <= TH.ece,
     'safety':     no_envelope_breach(model, probes.adversarial),
     'parity':     parity_ok(model),
     'uncertainty':abstains_outside_regime(model, probes.ood),
     'repro':      reproduces(model, tol=TH.repro)}
    return all(checks.values()), checks   # any False -> QUARANTINE

def guard(model, state, monitors):
    if monitors.breach(state):
        registry.log_rollback(model, cause=monitors.first_breach())
        if registry.prev_prod(model.name):
            return activate(registry.prev_prod(model.name))
        return L1.safe_state()          # model-free, certified path
    return model.act(state)

# Bradley-Terry reward model loss over preference pairs
def reward_loss(r, better, worse):
    return -torch.log(torch.sigmoid(r(better) - r(worse))).mean()

# Deploy as ensemble; use disagreement as epistemic signal
def reward_with_uncertainty(models, x):
    rs = torch.stack([m(x) for m in models])
    return rs.mean(0), rs.std(0)     # std -> penalty in RL objective

